import { loadFromGitHub } from 'gowm';

// Load image module from wasm-modules-repository
const image = await loadFromGitHub('benoitpetit/wasm-modules-repository', {
  path: 'image-wasm',
  name: 'image-wasm',
  branch: 'master'
});

// Configure module
image.call('setSilentMode', true);

// Convert file to base64
const fileInput = document.getElementById('imageFile');
const file = fileInput.files[0];
const base64 = await fileToBase64(file);

// Compress JPEG with error handling
const result = image.call('compressJPEG', base64, 80);
if (result.error) {
  console.error('Compression failed:', result.error);
} else {
  console.log('Original size:', result.originalSize, 'bytes');
  console.log('Compressed size:', result.newSize, 'bytes');
  console.log('Compression ratio:', result.compressionRatio);
}

// Helper function
function fileToBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result.split(',')[1]);
    reader.onerror = error => reject(error);
  });
}

// Complete image processing workflow
async function processImage(base64ImageData) {
  // Get original image info
  const info = image.call('getImageInfo', base64ImageData);
  if (info.error) {
    throw new Error('Failed to get image info: ' + info.error);
  }

  console.log('Original: ' + info.width + 'x' + info.height + ', ' + info.format + ', ' + info.size + ' bytes');

  // Resize if too large
  let processedImage = base64ImageData;
  if (info.width > 1920 || info.height > 1080) {
    const resizeResult = image.call('resizeImage', processedImage, 1920, 1080);
    if (resizeResult.error) {
      throw new Error('Resize failed: ' + resizeResult.error);
    }
    processedImage = resizeResult.processedImage;
    console.log('Resized to: ' + resizeResult.width + 'x' + resizeResult.height);
  }

  // Convert to WebP for better compression
  const webpResult = image.call('convertToWebP', processedImage, 85);
  if (webpResult.error) {
    throw new Error('WebP conversion failed: ' + webpResult.error);
  }

  console.log('Final WebP: ' + webpResult.newSize + ' bytes (' + webpResult.compressionRatio + '% of original)');
  return webpResult.processedImage;
}

// Helper function for consistent image processing error handling
function handleImageResult(result, successCallback, errorCallback) {
  if (result.error) {
    errorCallback(result.error);
  } else {
    successCallback(result);
  }
}

// Batch image processing with error handling
const images = [base64Image1, base64Image2, base64Image3];
const operations = [
  { func: 'compressJPEG', args: [80] },
  { func: 'convertToWebP', args: [85] },
  { func: 'resizeImage', args: [800, 600] }
];

images.forEach((imageData, imageIndex) => {
  operations.forEach(({ func, args }, opIndex) => {
    const result = image.call(func, imageData, ...args);
    handleImageResult(
      result,
      (data) => {
        console.log('Image ' + (imageIndex + 1) + ', ' + func + ': Success');
        console.log('  Original: ' + data.originalSize + ' bytes, New: ' + data.newSize + ' bytes');
        console.log('  Compression: ' + data.compressionRatio + '%');
      },
      (error) => {
        console.error('Image ' + (imageIndex + 1) + ', ' + func + ' failed: ' + error);
      }
    );
  });
});
